    spec_version, primary_media_id, version, created_by, create_time, updated_by, update_time
) VALUES (
    #{catalogCode}, #{name}, #{manufacturerId}, #{mpn}, #{normalizedMpn}, #{categoryId},
    #{packageType}, #{baseUnit}, #{description}, #{status}, #{currentSpecSnapshotId},
    #{specVersion}, #{primaryMediaId}, #{version}, #{createdBy}, #{createTime}, #{updatedBy}, #{updateTime}
)

